// Board data for Anon, the daily clueless acrostic. Imported ONLY by the server
// page (app/anon/page.js), which filters live<=today before handing the bank to
// the client, so tomorrow's passage never ships to a browser.
//
// A board is a PASSAGE and a BANK of answers. `q` is the passage, verbatim from
// a public-domain text; the letters of `q`, in order, are cells 0..n-1. Every
// answer in `a` lists the cells its letters occupy, so the two halves are the
// same letters seen twice and the cells partition the passage exactly.
//
// The first `spine` answers are the SPINE: their first letters spell `author`,
// which is the puzzle's payoff and the reason the game is called Anon. The rest
// are the free bank and carry no initial constraint, which is what leaves room
// for the closed categories.
//
// `cat` is the answer's category, and null means an OPEN answer with no category
// at all. A category is only worth printing when the solver can enumerate it:
// every non-null cat here admits at most FOUR words at that length, so 'planet, 5'
// is earth or venus and nothing else. That sharpness is the cold start.
//
// `closed` is how many answers carry a category and `forced` is how many words of
// the passage become uniquely determined once those answers fall. Both are
// recomputed from scratch by scripts/verify-anon.mjs, which trusts neither.
//
// Authoring floors, enforced by that verifier and NOT to be relaxed to make a
// board fit: no category admitting more than 4 words at its length, at least 32%
// of the passage forced by the closed answers alone, US spellings, answers
// distinct within a board, and the spine spelling the author exactly.
//
// The CLOSED floor is 6 for boards before 2026-09-30 and 10 from it. The earlier
// bank seated about 9 categories across 21 answers, and measured over Aug 7-23
// the median score among Anon's TOP TEN finishers was 48% of the board, while the
// top tens of Crux, Emcee and Garble were finishing 100%. The fix was the
// lexicon, not the passages: only 221 words in lib/anon-categories.js were both
// common enough to place and sharp at their length, and there are 459 now. The
// sharpness promise itself did not move, and must not: a printed category still
// admits at most four words at its length, which is the only reason printing one
// helps. See scripts/verify-anon.mjs for the bands and for why Sunday stopped
// being the coldest day of the week.
